"""Reproducible manuscript, figures and small sanitized evidence bundle."""
import json,shutil,subprocess
from datetime import datetime,timezone
from pathlib import Path
from xml.sax.saxutils import escape
import numpy as np,pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from ..util import save,file_hash
from .analysis import observations,contrasts,summary

def pct(x):return 'NA' if x is None else f'{100*x:.1f}%'
def number(x):return 'NA' if x is None else f'{x:.3f}'
def endpoint(m):
    ci=m.get('accuracy_ci95');rci=m.get('spearman_ci95')
    return f"{m['n_correct']:,}/{m['n_all']:,} = {pct(m['all_pair_accuracy'])}"+(f" (95% locus CI {pct(ci[0])}–{pct(ci[1])})" if ci else '')+f"; conditional {pct(m['conditional_accuracy'])} among {m['n_nonzero']:,}; zero {m['n_zero']:,}, missing {m['n_missing']:,}; rho {number(m['spearman'])}"+(f" (CI {number(rci[0])}–{number(rci[1])})" if rci else '')

def figures(out,m,sec,dev,geom):
    out=Path(out);figdir=out/'figures';figdir.mkdir(exist_ok=True);plt.rcParams.update({'font.size':9,'axes.spines.top':False,'axes.spines.right':False})
    arm=m['selection']['selected_arm'];arms=list(m['test']);f=observations(out,'test',arm);f=f[f.role=='candidate'];c=contrasts(out,'test',f)
    fig,ax=plt.subplots(2,2,figsize=(10,7));a=ax[0,0];a.scatter(c.observed,c.predicted,s=3,alpha=.2,rasterized=True);a.axhline(0,color='grey',lw=.6);a.axvline(0,color='grey',lw=.6);a.set(xlabel='Observed cell-effect contrast (SAIGE BETA)',ylabel='Predicted contrast (log(TPM+1))',title='A  Frozen cell contrasts')
    names=list(m['test'][arm]['per_cell']);values=np.array([[m['test'][a]['per_cell'][n]['all_pair_accuracy'] for a in arms] for n in names]);a=ax[0,1];im=a.imshow(values,vmin=0,vmax=1,cmap='viridis',aspect='auto');a.set_yticks(range(len(names)),names,fontsize=6);a.set_xticks(range(len(arms)),[s.replace('_',' ') for s in arms],rotation=15,fontsize=7);a.set_title('B  All-pair direction by cell');fig.colorbar(im,ax=a,shrink=.7)
    a=ax[1,0];x=np.arange(len(arms));a.bar(x-.18,[m['test'][s]['variant']['all_pair_accuracy'] for s in arms],.18,label='All pair');a.bar(x,[m['test'][s]['variant']['conditional_accuracy'] or 0 for s in arms],.18,label='Conditional');a.bar(x+.18,[m['test'][s]['variant']['n_zero']/m['test'][s]['variant']['n_all'] for s in arms],.18,label='Zero');a.set_xticks(x,[s.replace('_',' ') for s in arms],rotation=10,fontsize=7);a.set(ylim=(0,1),title='C  Denominators and abstention');a.legend(fontsize=7)
    a=ax[1,1];null=pd.read_csv(out/f'null_{arm}.tsv',sep='\t');a.hist(null.cell_accuracy,bins=35,color='#577d9d');a.axvline(m['test'][arm]['cross_cell']['all_pair_accuracy'],color='#bb4a32',label='Observed');a.set(xlabel='All-pair cell direction under shuffled labels',title='D  Within-locus cell-label null');a.legend();fig.tight_layout();fig.savefig(figdir/'primary.png',dpi=180);plt.close(fig)
    fig,ax=plt.subplots(2,2,figsize=(10,7));a=ax[0,0];labels=list(dev['arms']);vals=[dev['arms'][k]['cross_cell']['all_pair_accuracy'] for k in labels];lo=[dev['arms'][k]['cross_cell']['accuracy_ci95'][0] for k in labels];hi=[dev['arms'][k]['cross_cell']['accuracy_ci95'][1] for k in labels];a.errorbar(vals,np.arange(len(labels)),xerr=[np.array(vals)-lo,np.array(hi)-vals],fmt='o',capsize=2);a.set_yticks(range(len(labels)),[k.replace('baseline_plus_','+').replace('_',' ') for k in labels],fontsize=6);a.set(xlabel='Development cell contrast direction',title='A  Entire description family (95% locus CI)')
    a=ax[0,1];coef=m['test'][arm]['development_fit_calibration'];ok=f.delta.notna();x=coef['intercept']+coef['slope']*f.delta[ok];a.scatter(x,f.beta[ok],s=3,alpha=.2);a.set(xlabel='Predicted BETA, development calibration',ylabel='Observed test BETA',title='B  Test calibration (no refitting)')
    a=ax[1,0];families=sec[arm]['family'];fn=list(families);a.barh(fn,[families[k]['n_all'] for k in fn]);a.set(xlabel='Candidate variant–cell observations',title='C  Family coverage (power differs)')
    a=ax[1,1];g=pd.read_parquet(out/'geometry_results.parquet');a.scatter(g.delta_40960,g.delta,s=12,c=g.valid_comparison.map({True:'#286c62',False:'#b85b42'}));a.set(xlabel='40960-bp delta',ylabel='81920-bp apparent delta',title='D  Geometry sensitivity (red invalid spans)');fig.tight_layout();fig.savefig(figdir/'secondary.png',dpi=180);plt.close(fig)
    fig,ax=plt.subplots(figsize=(9,2.5));ax.axis('off');flow=pd.read_csv(out/'cohort_flow.tsv',sep='\t');text=' → '.join(f"{r.stage.replace('_',' ')}\n{r.pairs:,}" for r in flow.itertuples());ax.text(.5,.62,text,ha='center',va='center',fontsize=11);ax.text(.5,.2,'Historical 167 genes excluded with their transitive ±100-kb TSS clusters\nTest: 1,000 candidates + 1,000 uncertain controls; 777 clusters; 28 populations',ha='center',fontsize=10);fig.tight_layout();fig.savefig(figdir/'flow.png',dpi=180);plt.close(fig)
    return figdir

def report(out):
    out=Path(out)
    from .qa import qa
    quality=qa(out)
    m=json.load(open(out/'metrics.json'));sec=json.load(open(out/'secondary_metrics.json'));dev=json.load(open(out/'development_inference.json'));geom=json.load(open(out/'geometry_metrics.json'));frozen=json.load(open(out/'frozen_protocol.json'));pre=json.load(open(out/'api_preflight.json'));env=json.load(open(out/'environment.json'));figures(out,m,sec,dev,geom)
    # Consolidated redacted usage, including preflight and separate geometry.
    ledgers=[];responses=[]
    for name in ['followup-smoke','followup-v1','followup-geometry']:
        root=Path('data/cache')/name
        if (root/'requests.jsonl').exists():ledgers.extend(json.loads(l) for l in (root/'requests.jsonl').open())
        if (root/'responses.jsonl').exists():responses.extend(json.loads(l) for l in (root/'responses.jsonl').open())
    with (out/'requests.jsonl').open('w') as h:
        for r in ledgers:h.write(json.dumps(r)+'\n')
    from collections import Counter
    usage={'requests':len(ledgers),'unique_cache_keys':len({r['cache_key'] for r in ledgers}),'response_statuses':dict(Counter(str(r['status']) for r in responses)),'total_call_cap':None};save(out/'usage.json',usage)
    selection=m['selection']['selected_arm'];base=m['test']['baseline'];B=base['variant'];A=base['cross_cell'];p=base['primary_tests'];testn=frozen['counts']['test'];date=datetime.now(timezone.utc).strftime('%d %B %Y')
    sections=[]
    def add(name,text):sections.append((name,text))
    add('Abstract',f"We evaluated GI DNA-to-expression predictions using an independent follow-up to an exploratory TenK10K pilot. A complete historical request audit excluded previously scored loci. We froze 250 development loci and {testn['pairs']:,} test variant–gene pairs across {testn['loci']:,} physical locus clusters, with matched uncertain controls and 28 immune-cell populations. Baseline all-pair variant direction was {pct(B['all_pair_accuracy'])} ({B['n_correct']:,}/{B['n_all']:,}); cross-cell contrast direction was {pct(A['all_pair_accuracy'])} ({A['n_correct']:,}/{A['n_all']:,}), with rho {number(A['spearman'])}. The development-selected gene-free configuration was {selection}. Both endpoints count near-zero predictions as incorrect. Locus-cluster intervals and multiplicity-adjusted tests are reported. The assessment tests generalization beyond prior API experiments, not independence from the model's unknown training corpus.")
    add('Introduction',"A useful regulatory sequence model should predict both the sign of an allelic effect and how that effect differs between cell types. TenK10K provides summary-level estimates for this assessment. The Nature version of record [1] supersedes the linked medRxiv preprint [2]; they are versions of one study. Our previous pilot and text experiments were exploratory and motivated this independent cohort rather than serving as confirmatory evidence.")
    add('Methods: data and isolation',"We used only Zenodo record 18221260 [3] for association summaries, official GRCh38 primary sequence and GENCODE v44 annotations [4]. Three archive checksums and SHA256 values were verified; all 28 full-summary ZIP members were streamed with schema and CRC checks, without downloading donor-level data. Canonical annotation required an unambiguous TSS among tagged canonical/MANE transcripts. Candidate SNVs required PIP ≥0.90 in a significant discovery gene–cell association (per-cell BH q≤0.05), MAF≥0.01, complete finite effect/SE and verified genomic REF. We recovered 2,783 cached historical request keys plus one uncached positive control, spanning 167 genes. Historic and eligible prospective TSS ±100-kb windows were merged transitively, and entire historical-containing clusters excluded. Development and test share no cluster or gene. These physical clusters approximate dependence; matched LD blocks were unavailable.")
    add('Methods: matched inputs and GI inference',"Each candidate received one fixed uncertain control in the same gene, with MAF difference≤0.05 in each selected cell, absolute TSS-distance difference≤5 kb and 201-bp reference GC difference≤0.10. Reported control PIP had to be below 0.5; missing PIP stayed unknown. Discovery plus related/distant cells (up to six) and all cell contrasts were selected before inference. SAIGE-QTL Allele2=ALT determined observed BETA orientation. SNVs were edited on genomic-plus sequence before reverse complementation for minus-strand genes. GI g0-expression-8192 [5] used 40,960 bases and oriented TSS index20,480. REF/ALT text and effective scoring spans had to match, with the variant covered. Predicted effect was ALT−REF in log(TPM+1). A distinct cache binds exact sequence hashes, model, description, API contract, geometry and options; bounded retries and adaptive pacing preserve resumability without a total-call limit. The 3-prime assay is confirmed in the Nature methods; unstimulated refers to the absence of a described experimental stimulation arm, not absence of endogenous activation. The catalog supplies an ID, but no immutable model-weight digest; silent server updates cannot be ruled out.")
    add('Methods: context selection and statistics',"All ten description arms were evaluated on development only. Gene-symbol and Ensembl arms were separated as gene-aware exploratory conditioning. A gene-free alternative required ≥3 percentage-point gain in all-pair cross-cell direction and ≤3 percentage-point coverage loss; ties used contrast rho then variant direction. Otherwise baseline was retained. The exact registry, source/cohort hashes, analysis plan and implementation hashes were locked before test inference. Zeros (|delta|≤10^-6) and unscored rows remain in all-pair direction denominators; rho retains numerical zeros and reports missing coverage. We used 3,000 physical-locus bootstrap resamples and 2,000 clustered randomizations. Co-primary A uses the larger of direction and rho cell-label permutation p-values; B uses a locus effect-sign null. Holm adjusts A/B; the prespecified direction decision additionally requires >50% all-pair accuracy; below this floor the co-primary p-value is conservatively set to1 before Holm. The raw zero-preserving randomization p-values remain in metrics.json. The informative contrast stratum |beta_a−beta_b|>2(SE_a+SE_b) is descriptive because cross-cell covariance is unknown. Affine scale calibration was fitted only on development.")
    add('Results: independent test',f"Acceptance checks passed {quality['passed']}/{quality['passed']+quality['failed']}, with {quality['reference_variants_checked']:,} reference variants verified and {quality['reference_failures']} failures; {quality['unit_tests']}. The frozen test comprised {testn['pairs']:,} candidates, the same number of uncertain controls, {testn['loci']:,} clusters and {testn['observations']:,} candidate/control variant–cell rows. The available matched reserve did not reach the 2,000-pair expansion target; no PIP relaxation was used. Baseline variant effects: {endpoint(B)}. Baseline cross-cell contrasts: {endpoint(A)}. Holm-adjusted co-primary p-values were A={number(p['holm_A_B'][0])} and B={number(p['holm_A_B'][1])}. The cross-cell rho CI lower bound {'exceeded zero' if A.get('spearman_ci95') and A['spearman_ci95'][0]>0 else 'did not exceed zero'}. The descriptive precision stratum yielded {endpoint(base['precision_contrasts'])}.")
    if selection!='baseline':
        alt=m['test'][selection];paired=m['paired_alternative'];add('Results: frozen description comparison',f"The alternative {selection} yielded variant {endpoint(alt['variant'])}, and cross-cell {endpoint(alt['cross_cell'])}. Paired cross-cell gain was {100*paired['cross_cell']['gain']:.2f} percentage points (95% locus CI {100*paired['cross_cell']['ci95'][0]:.2f} to {100*paired['cross_cell']['ci95'][1]:.2f}); paired variant gain was {100*paired['variant']['gain']:.2f} points. Separate Holm-adjusted improvement p-values (cross-cell, variant) were {paired['holm_p']}. No test outcomes were used for further prompt tuning.")
    else:add('Results: frozen description comparison',"No gene-free development arm satisfied the frozen gain/coverage rule; baseline was retained. Consequently only baseline was scored on test, with no second description chosen after viewing test outcomes.")
    add('Results: controls and diagnostics',f"Uncertain controls under baseline: {endpoint(base['uncertain_controls'])}. Matched magnitude ranking counts: {base['candidate_control_ranking']}. These are prioritization summaries, not causal classification accuracy. Six input-only Reactome98 immune regulatory strata, fixed before test inference, are reported with locus intervals in secondary_metrics.json; no pathway-specific significance is claimed. The full development arm matrix with locus intervals and nine-arm Holm comparisons is supplied in development_inference.json and Figure2A. Swapped gene identifiers, a nonsense gene identifier and shuffled cell labels were tested on a fixed 25-locus development subset; their complete denominators and paired intervals are supplied separately. Exact historical-locus repeat checks agreed in {sum(x['exact_repeat_equal'] for x in pre['checks'])}/{len(pre['checks'])} cases. Larger geometry diagnostics: {geom['n_attempted']}/{geom['n_preselected']} prespecified development loci evaluated; {geom['n_exact_effective_spans']} had identical covered REF/ALT spans. Invalid long-window deltas are shown only as geometry diagnostics and excluded from biological sensitivity estimates.")
    add('Discussion: relation to the Nature study',"Cuomo et al. [1] mapped genetic effects in 28 immune populations and reported substantial cell specificity. Their PromoterAI analysis reported median correlation0.66 between promoter scores and lead-eQTL effects. PromoterAI uses a specialized promoter-variant task and a different selected variant population. Our pooled Spearman estimates, high-PIP ascertainment, zeros, cell contrasts and input geometry differ; subtracting these correlations or claiming model superiority would be invalid. No licensed matched PromoterAI predictions were supplied, and AlphaGenome/Borzoi were not executed on this cohort. The comparison is narrative, not head-to-head. The broader implication is that variant-effect agreement and prediction of cell-specific differences require separate evidence; a favorable conditional sign score alone cannot establish the latter.")
    add('Discussion: limitations',"High-PIP significant-gene selection enriches detectable associations and limits generalization to all variants, distal regulation, indels and rare alleles. Requiring both candidate and control estimates in several cells also favors expressed genes. Observational fine-mapping is not experimental causality. Cell labels are approximations, and exact ontology mappings were unavailable for some populations. Physical locus clusters do not establish LD independence; unequal cell sample sizes and unknown cross-cell covariance complicate precision comparisons. GI training overlap is unknown, and development prompt selection is target-informed even though frozen test genes are unseen by these API experiments. API output quantization can create ties. SAIGE Poisson coefficients and GI log(TPM+1) changes have different scales; empirical calibration does not repair all biological differences. Six immune regulatory pathway strata used fixed Reactome98 membership and exact GENCODE44 symbols; overlapping sets and low gene counts make these descriptive. Independent caQTL replication was not run because no matching authorized source was included. All absent analyses are explicitly marked in secondary_metrics.json.")
    add('Reproducibility and availability',f"Code and sanitized aggregates: https://github.com/burtsev/GxI-TenK10K . Full local evidence: {out}. Execution source revision recorded by preflight: {env['git_commit']}; pre-test implementation hashes are in code_manifest.json. Model g0-expression-8192, API2026.10.19.2 (afabae26), contract SHA256 {pre['sources']['gi_openapi.json']['sha256']}; GRCh38/GENCODE44; seed20261030. Recorded API attempts: {usage['requests']:,}; statuses {usage['response_statuses']}. Raw archives, DNA and response caches remain local. Reproduce using the pinned requirements and followup CLI audit, freeze, score-dev, diagnostics, select-context, score-test, geometry, evaluate, report. This computational manuscript was generated for project review and has not been submitted to bioRxiv or peer reviewed.")
    add('References',"[1] Cuomo ASE et al. Rare and common genetic variants shape single-cell immune gene expression. Nature (2026), published28 October2026. https://doi.org/10.1038/s41586-026-10721-2\n\n[2] Source preprint v2: https://www.medrxiv.org/content/10.1101/2025.03.20.25324352v2\n\n[3] TenK10K Phase1 summary release. https://doi.org/10.5281/zenodo.18221260\n\n[4] GENCODE human release44. https://www.gencodegenes.org/human/release_44.html\n\n[5] GI API documentation. https://docs.genomicintelligence.ai/rest-api.md\n\n[6] PromoterAI software and license terms. https://github.com/Illumina/PromoterAI")
    title='Independent assessment of DNA-to-expression variant effects and immune-cell specificity with Genomic Intelligence'
    text='# '+title+'\n\nComputational research report | '+date+' | Manuscript for project review\n\n'+'\n\n'.join('## '+n+'\n\n'+t for n,t in sections)
    text+='\n\n## Entire development family\n\n| Arm | Gene-aware | Cell correct/all | Cell rho | Variant correct/all |\n|---|---|---|---|---|\n'
    for arm,r in dev['arms'].items():text+=f"| {arm} | {r['gene_aware']} | {r['cross_cell']['n_correct']}/{r['cross_cell']['n_all']} | {number(r['cross_cell']['spearman'])} | {r['variant']['n_correct']}/{r['variant']['n_all']} |\n"
    legacy_frame=pd.read_csv('docs/runs/live-20261029/measured_predictions.tsv',sep='\t');legacy_frame=legacy_frame[legacy_frame.category=='candidate']
    legacy_cells=pd.read_csv('docs/runs/live-20261029/trial_cell_contrasts.tsv',sep='\t')
    legacy_metrics={'variant':summary(legacy_frame.beta_alt,legacy_frame.delta,legacy_frame.locus,B=3000),'cross_cell_trial_only':summary(legacy_cells.beta_alt,legacy_cells.delta,legacy_cells.locus,B=3000)}
    save(out/'legacy_comparison_metrics.json',legacy_metrics)
    text+='\n## Legacy and independent study comparison\n\n| Cohort | Status | All-pair variant direction | Conditional | Cross-cell all-pair |\n|---|---|---|---|---|\n| Legacy original100 | Exploratory, amended | 52/100 | 52/77 | 32/81 (17 genes, trial cell contrasts) |\n'
    for arm,r in m['test'].items():text+=f"| Fresh test {arm} | Frozen independent API experiment | {r['variant']['n_correct']}/{r['variant']['n_all']} | {r['variant']['n_correct']}/{r['variant']['n_nonzero']} | {r['cross_cell']['n_correct']}/{r['cross_cell']['n_all']} |\n"
    text+='\nLegacy uncertainty, recomputed with the same locus-bootstrap code: variant '+endpoint(legacy_metrics['variant'])+'; trial cell contrasts '+endpoint(legacy_metrics['cross_cell_trial_only'])+'. The legacy cell contrasts use the comparison-trial subset, not all100 pilot genes; their ascertainment differs from the new test.\n'
    # Original cell-contrast denominator must be read from the historical evidence.
    legacy=Path('docs/runs/live-20261029/cell_contrast_metrics.json')
    if legacy.exists():
        old=json.load(legacy.open());save(out/'legacy_comparison_source.json',old)
    (out/'report.md').write_text(text)
    pdf=build_pdf(out,title,date,sections)
    small=Path('docs/runs/followup-20261030');small.mkdir(parents=True,exist_ok=True)
    for name in ['report.md','legacy_comparison_metrics.json','metrics.json','secondary_metrics.json','development_arm_metrics.json','development_inference.json','geometry_metrics.json','usage.json','qa.json','data_verification.json','frozen_protocol.json','cohort_hashes.json','context_selection.json','analysis_plan.json','code_manifest.json','source_manifest.json','environment.json','api_preflight.json','cohort_flow.tsv','amendments.md','cell_mapping.tsv']:
        shutil.copy2(out/name,small/('summary.md' if name=='report.md' else name))
    shutil.copy2(out/'recovery/recovery_audit.json',small/'recovery_audit.json');shutil.copy2(out/'recovery/legacy_exclusions.tsv',small/'legacy_exclusions.tsv')
    shutil.copy2(pdf,small/pdf.name)
    for name in ['primary.png','secondary.png','flow.png']:
        (small/'figures').mkdir(exist_ok=True);shutil.copy2(out/'figures'/name,small/'figures'/name)
    manifest={'report_pdf':str(pdf),'sha256':file_hash(pdf),'bytes':pdf.stat().st_size,'generated_utc':datetime.now(timezone.utc).isoformat(),'status':'complete','local_results':str(out),'frozen_test':frozen['counts']['test']};save(out/'report_manifest.json',manifest);save(small/'report_manifest.json',manifest)
    return manifest

def build_pdf(out,title,date,sections):
    from reportlab.platypus import BaseDocTemplate,PageTemplate,Frame,Paragraph,Spacer,PageBreak,NextPageTemplate,Image
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.enums import TA_JUSTIFY
    W,H=A4;M=42;gap=18;cw=(W-2*M-gap)/2
    body=ParagraphStyle('body',fontName='Times-Roman',fontSize=9.3,leading=11.4,alignment=TA_JUSTIFY,spaceAfter=6)
    head=ParagraphStyle('head',parent=body,fontName='Times-Bold',fontSize=10.5,leading=12.2,spaceBefore=6)
    title_style=ParagraphStyle('title',fontName='Times-Bold',fontSize=20,leading=23,spaceAfter=10)
    def para(s,style=body):return Paragraph(escape(s).replace('\n','<br/>').replace('≥','&gt;=').replace('≤','&lt;='),style)
    def footer(can,doc):
        can.saveState();can.setFont('Times-Roman',7.5);can.drawString(M,22,'GI × TenK10K | Independent follow-up | Research manuscript, not peer reviewed');can.drawRightString(W-M,22,str(doc.page));can.restoreState()
    pdf=out/'GI_TenK10K_followup_manuscript.pdf';doc=BaseDocTemplate(str(pdf),pagesize=A4,title=title,author='GI × TenK10K benchmark project',pageCompression=1)
    full=Frame(M,42,W-2*M,H-84,id='full',leftPadding=0,rightPadding=0,topPadding=0,bottomPadding=0)
    columns=[Frame(M,42,cw,H-84,id='l',leftPadding=0,rightPadding=0,topPadding=0,bottomPadding=0),Frame(M+cw+gap,42,cw,H-84,id='r',leftPadding=0,rightPadding=0,topPadding=0,bottomPadding=0)]
    doc.addPageTemplates([PageTemplate(id='front',frames=[full],onPage=footer),PageTemplate(id='text',frames=columns,onPage=footer),PageTemplate(id='figures',frames=[full],onPage=footer)])
    story=[para(title,title_style),para('GI × TenK10K benchmark project | '+date),para('Abstract',head),para(sections[0][1]),Spacer(1,12),Image(str(out/'figures/flow.png'),width=W-2*M,height=(W-2*M)*2.5/9),para('Data and code: github.com/burtsev/GxI-TenK10K. Frozen independent development/test split; no previous API-tested loci in confirmation.'),NextPageTemplate('text'),PageBreak()]
    for name,text in sections[1:]:
        story.append(para(name,head))
        story.extend(para(t) for t in text.split('\n\n'))
    story.extend([NextPageTemplate('figures'),PageBreak(),para('Figure 1. Independent test results',head),Image(str(out/'figures/primary.png'),width=W-2*M,height=(W-2*M)*.7),para('A: fixed candidate cell contrasts; units differ across axes. B: all-pair variant direction by population. C: all-pair and conditional success with separate zero rate. D: within-locus shuffled-cell null; red line is the observed statistic. All model zeros remain in the all-pair denominator.'),PageBreak(),para('Figure 2. Development, calibration and geometry',head),Image(str(out/'figures/secondary.png'),width=W-2*M,height=(W-2*M)*.7),para('A: complete development family, including the separate gene-aware track, with locus intervals. B: test evaluation of development-fitted calibration. C: family sample sizes. D: longer-window apparent deltas; red points fail the identical-effective-span rule and are not valid biological effects.')])
    doc.build(story);return pdf
